INSERT INTO _migration_492_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igbio_respiration_s2_001', 'topic_igcse_bio_respiration', 'subj_igcse_biology', 'igcse', NULL, NULL, 'Which gas is released as a waste product of aerobic respiration?', 'multiple_choice', NULL, '["A. Carbon dioxide","B. Oxygen","C. Nitrogen","D. Methane"]', 'A', 'Aerobic respiration breaks down glucose using oxygen, releasing energy and producing carbon dioxide and water; the carbon dioxide diffuses into the blood and is exhaled from the lungs. Oxygen is a reactant rather than a product, nitrogen passes through the lungs unchanged, and methane is not produced by human cells. Therefore the correct answer is A: Carbon dioxide.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Recall', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igbio_respiration_s2_002', 'topic_igcse_bio_respiration', 'subj_igcse_biology', 'igcse', NULL, NULL, 'Where does gas exchange between the air and the blood take place in the lungs?', 'multiple_choice', NULL, '["A. In the trachea","B. In the alveoli","C. In the bronchi","D. In the larynx"]', 'B', 'The alveoli are tiny air sacs with thin walls, a moist surface, a rich blood supply and a huge surface area, which makes them the site of gas exchange. The trachea, bronchi and larynx are conducting airways with thick walls, and no significant gas exchange occurs across them. Therefore the correct answer is B: In the alveoli.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igbio_respiration_s2_003', 'topic_igcse_bio_respiration', 'subj_igcse_biology', 'igcse', NULL, NULL, 'Why does a person''s breathing rate increase during vigorous exercise?', 'multiple_choice', NULL, '["A. To cool the body by blowing out warm air","B. To pump blood faster around the body","C. To supply more oxygen to the muscles and remove the extra carbon dioxide produced by respiration","D. To help the stomach digest food more quickly"]', 'C', 'During exercise the muscle cells respire faster, using more oxygen and releasing more carbon dioxide, so faster and deeper breathing brings in extra oxygen and expels the extra carbon dioxide to keep the blood gases balanced. Breathing is not a cooling mechanism, the heart rather than the lungs pumps blood faster, and the breathing rate does not affect digestion. Therefore the correct answer is C: To supply more oxygen to the muscles and remove the extra carbon dioxide produced by respiration.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_cambridge'),
('q_igbio_respiration_s2_004', 'topic_igcse_bio_respiration', 'subj_igcse_biology', 'igcse', NULL, NULL, 'Which word equation summarises anaerobic respiration in yeast?', 'multiple_choice', NULL, '["A. Glucose → lactic acid","B. Glucose + oxygen → carbon dioxide + water","C. Carbon dioxide + water → glucose + oxygen","D. Glucose → alcohol + carbon dioxide"]', 'D', 'In yeast, anaerobic respiration (fermentation) converts glucose to alcohol (ethanol) and carbon dioxide, releasing a small amount of energy without using oxygen. Glucose → lactic acid is anaerobic respiration in human muscle, glucose + oxygen → carbon dioxide + water is aerobic respiration, and carbon dioxide + water → glucose + oxygen is photosynthesis. Therefore the correct answer is D: Glucose → alcohol + carbon dioxide.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igbio_respiration_s2_005', 'topic_igcse_bio_respiration', 'subj_igcse_biology', 'igcse', NULL, NULL, 'Which feature of the alveoli shortens the diffusion distance for gases?', 'multiple_choice', NULL, '["A. Walls that are only one cell thick","B. A thick layer of cartilage around each alveolus","C. A dry inner surface","D. A small total surface area"]', 'A', 'The alveolar wall and the surrounding capillary wall are each only one cell thick, so oxygen and carbon dioxide have a very short distance to diffuse between the air and the blood. Cartilage supports the larger airways and would slow diffusion, the alveolar surface is moist so gases can dissolve, and the total surface area of the alveoli is very large rather than small. Therefore the correct answer is A: Walls that are only one cell thick.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igbio_respiration_s2_006', 'topic_igcse_bio_respiration', 'subj_igcse_biology', 'igcse', NULL, NULL, 'What happens to the diaphragm and the rib cage when a person breathes in?', 'multiple_choice', NULL, '["A. The diaphragm relaxes and domes upwards, and the ribs move up and out","B. The diaphragm contracts and flattens, and the ribs move up and out","C. The diaphragm contracts and flattens, and the ribs move down and in","D. The diaphragm relaxes and domes upwards, and the ribs move down and in"]', 'B', 'Breathing in (inhalation) is driven by the diaphragm contracting and flattening while the external intercostal muscles pull the ribs up and out, increasing the volume of the thorax so air is drawn in. A relaxing, domed diaphragm with the ribs moving down and in describes breathing out, and the mixed combinations cannot produce the volume increase needed for inhalation. Therefore the correct answer is B: The diaphragm contracts and flattens, and the ribs move up and out.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Apply', 'AO2', NULL, NULL, 'board_cambridge');
INSERT INTO _migration_492_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_492_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_492_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'igcse-bio-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Biology (0610) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-biology-0610/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_492_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'igcse-bio-sprint2-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Biology (0610) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.', 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-biology-0610/', 0, 1 FROM _migration_492_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_492_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_492_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 6 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_492_expected e ON e.id = r.question_id WHERE r.batch_id IS 'igcse-bio-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Biology (0610) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-biology-0610/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 6 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_492_expected e ON e.id = q.id) = 6 THEN 1 ELSE 0 END;
